package com.hfr.packet.builder;
import com.hfr.builder.BuilderDepotService;import com.hfr.tileentity.machine.TileEntityMachineBuilder;import cpw.mods.fml.common.network.simpleimpl.*;import io.netty.buffer.ByteBuf;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.tileentity.TileEntity;
public class BuilderDepotRequestPacket implements IMessage {public int dimension,x,y,z;public BuilderDepotRequestPacket(){}public BuilderDepotRequestPacket(int d,int x,int y,int z){dimension=d;this.x=x;this.y=y;this.z=z;}public void fromBytes(ByteBuf b){dimension=b.readInt();x=b.readInt();y=b.readInt();z=b.readInt();}public void toBytes(ByteBuf b){b.writeInt(dimension);b.writeInt(x);b.writeInt(y);b.writeInt(z);}public static class Handler implements IMessageHandler<BuilderDepotRequestPacket,IMessage>{public IMessage onMessage(BuilderDepotRequestPacket m,MessageContext c){EntityPlayerMP p=c.getServerHandler().playerEntity;if(p==null||p.dimension!=m.dimension)return null;TileEntity te=p.worldObj.getTileEntity(m.x,m.y,m.z);if(!(te instanceof TileEntityMachineBuilder))return null;TileEntityMachineBuilder d=(TileEntityMachineBuilder)te;com.hfr.entity.EntityFactionBuilder worker=d.getLoadedBuilder();if(p.getDistanceSq(m.x+.5,m.y+.5,m.z+.5)>64&&(worker==null||p.getDistanceSqToEntity(worker)>64))return null;if(!BuilderDepotService.mayView(p,d))return null;return BuilderDepotSnapshotPacket.create(d);}}}
